cd <TMP>/rampcheck && cat > shot.js <<'EOF'
const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({ args: ['--use-gl=swiftshader', '--enable-unsafe-swiftshader'] });
  const errors = [];
  const run = async (name, opts, action) => {
    const ctx = await browser.newContext(opts);
    const page = await ctx.newPage();
    page.on('pageerror', (e) => errors.push(`${name} pageerror: ${e.message}`));
    page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') errors.push(`${name} console.${m.type()}: ${m.text()}`); });
    await page.goto('file:///app/index.html');
    await page.waitForTimeout(1500);
    if (action) await action(page);
    await page.screenshot({ path: `<TMP>/rampcheck/${name}.png` });
    await ctx.close();
  };
  await run('desktop', { viewport: { width: 1440, height: 900 } });
  await run('mobile', { viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true });
  await run('hover', { viewport: { width: 1440, height: 900 } }, async (p) => {
    for (let i = 0; i < 25; i++) { await p.mouse.move(560 + i * 12, 520 + Math.sin(i / 3) * 40); await p.waitForTimeout(30); }
    await p.waitForTimeout(200);
  });
  await run('reduced', { viewport: { width: 1440, height: 900 }, reducedMotion: 'reduce' });
  await run('landscape-phone', { viewport: { width: 844, height: 390 }, deviceScaleFactor: 2 });
  console.log(errors.length ? errors.join('\n') : 'NO ERRORS');
  await browser.close();
})().catch((e) => { console.error('FAILED:', e.message); process.exit(1); });
EOF
timeout 300 node shot.js 2>&1 | tail -30; ls -la <TMP>/rampcheck/*.png 2>/dev/null

