const NOODLE_TONES = ['#f7d98c', '#eec46f', '#fbe6ad', '#e9b25a'];
const noodles = [];
for (let n = 0; n < 72; n++) {
  // Strands gather into a mound toward the centre of the bowl
  const a = range(0, TAU), r = Math.pow(rand(), 0.8) * 0.5;
  let u = Math.cos(a) * r, v = Math.sin(a) * r;
  let heading = range(0, TAU);
  const ctrl = [[u, v]];
  const segments = 5 + Math.floor(rand() * 3);
  for (let k = 0; k < segments; k++) {
    heading += Math.sin(k * 2.1 + n) * 0.9 + range(-0.3, 0.3);   // crimped, wavy strands
    u += Math.cos(heading) * range(0.08, 0.12);
    v += Math.sin(heading) * range(0.08, 0.12);
    const d = Math.hypot(u, v);
    if (d > 0.86) { u *= 0.86 / d; v *= 0.86 / d; }
    ctrl.push([u, v]);
  }
  const centre = 1 - r / 0.5;                                    // strands in the middle rise highest
  noodles.push({
    pts: Float32Array.from(catmull(ctrl, 5).flat()),
    tone: pick(NOODLE_TONES),
    width: range(3.6, 5),
    submerged: rand() < 0.3,
    lift: rand() < 0.5 ? range(2, 6) * centre : 0,
    phase: range(0, TAU)
  });
