cd <TMP>/rampcheck && cat > probe.js <<'EOF'
const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await (await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1 })).newPage();
  await page.goto('file:///app/index.html');
  await page.waitForTimeout(800);
  const col = await page.evaluate(() => {
    const c = document.getElementById('scene');
    const g = c.getContext('2d');
    const out = [];
    for (let y = 560; y <= 650; y += 1) {
      const d = g.getImageData(60, y, 1, 1).data;
      out.push([y, d[0], d[1], d[2]]);
    }
    return out;
  });
  // report the largest step between consecutive rows
  let worst = { d: 0 };
  for (let i = 1; i < col.length; i++) {
    const d = Math.abs(col[i][1] - col[i-1][1]) + Math.abs(col[i][2] - col[i-1][2]) + Math.abs(col[i][3] - col[i-1][3]);
    if (d > worst.d) worst = { d, y: col[i][0], a: col[i-1].slice(1), b: col[i].slice(1) };
  }
  console.log(JSON.stringify(col.filter((_, i) => i % 6 === 0)));
  console.log('largest 1px step:', JSON.stringify(worst));
  await browser.close();
})().catch(e => { console.error(e.message); process.exit(1); });
EOF
