const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const errors = [];
  const ctx = await browser.newContext({ viewport: { width: 1280, height: 800 } });
  const page = await ctx.newPage();
  page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
  page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  await page.goto('file:///app/index.html');
  await page.waitForTimeout(800);
  // mouse sweep across the broth, then clicks
  for (let i = 0; i < 40; i++) { await page.mouse.move(420 + i * 9, 430 + Math.sin(i / 4) * 30); await page.waitForTimeout(16); }
  await page.mouse.down(); await page.waitForTimeout(60); await page.mouse.up();
  await page.mouse.move(640, 470); await page.waitForTimeout(300);
  await page.screenshot({ path: '<TMP>/rampcheck/interact_after_mouse.png' });
  // leave the window, then reduced-motion is toggled live
  await page.evaluate(() => document.dispatchEvent(new PointerEvent('pointerout', { bubbles: true, relatedTarget: null })));
  await page.emulateMedia({ reducedMotion: 'reduce' });
  await page.waitForTimeout(400);
  await page.screenshot({ path: '<TMP>/rampcheck/interact_reduced_live.png' });
  await page.emulateMedia({ reducedMotion: 'no-preference' });
  await page.waitForTimeout(400);
  // resize through several shapes
  for (const [w, h] of [[390, 844], [1920, 1080], [844, 390]]) {
    await page.setViewportSize({ width: w, height: h });
    await page.waitForTimeout(300);
  }
  await page.screenshot({ path: '<TMP>/rampcheck/interact_resized.png' });
  const tapCtx = await browser.newContext({ viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true });
  const tap = await tapCtx.newPage();
  tap.on('pageerror', (e) => errors.push('touch pageerror: ' + e.message));
  await tap.goto('file:///app/index.html');
  await tap.waitForTimeout(500);
  await tap.touchscreen.tap(195, 470);
  await tap.waitForTimeout(300);
  console.log(errors.length ? errors.join('\n') : 'NO ERRORS');
  await browser.close();
})().catch((e) => { console.error('FAILED:', e.message); process.exit(1); });
EOF
